76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
105	        if (normalizedTelephone == null) {
106	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
107	        }
108	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
109	            return new ResponseEntity<>(HttpStatus.CONFLICT);
110	        }
111	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
112	            && isHouseholdDuplicate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress())) {
113	            return new ResponseEntity<>(HttpStatus.CONFLICT);
114	        }
115	        HttpHeaders headers = new HttpHeaders();
116	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
117	        owner.setTelephone(normalizedTelephone);
118	        if (owner.getRegistrationDate() == null) {
119	            owner.setRegistrationDate(LocalDate.now());
120	        }
121	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
122	        this.clinicService.saveOwner(owner);
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        headers.setLocation(UriComponentsBuilder.newInstance()
125	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
126	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
132	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
133	        if (currentOwner == null) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
137	        if (normalizedTelephone == null) {
138	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
139	        }
140	        currentOwner.setAddress(ownerFieldsDto.getAddress());
141	        currentOwner.setCity(ownerFieldsDto.getCity());
142	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
143	        currentOwner.setLastName(ownerFieldsDto.getLastName());
144	        currentOwner.setTelephone(normalizedTelephone);
145	        currentOwner.setEmail(ownerFieldsDto.getEmail());
146	        this.clinicService.saveOwner(currentOwner);
147	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
148	    }
