151	    @Transactional
152	    @Override
153	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        this.clinicService.deleteOwner(owner);
159	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
160	    }
